#!/usr/bin/env node
/**
 * Snapshot VIVA's station roster (id, name, lat, lon) into
 * lib/viva-stations.snapshot.ts, used as a fallback when the live roster
 * request fails at runtime.
 *
 * Run from a machine that can reach sjofartsverket.se (any dev machine):
 *
 *   npm run snapshot:viva
 *
 * then commit the regenerated file. Re-run occasionally — stations come and go.
 */
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const URL =
  'https://services.viva.sjofartsverket.se:8080/output/vivaoutputservice.svc/vivastation/';

// Trailing slash AND Accept: application/json are both required; without them
// the WCF service returns an HTML help page instead of JSON.
let res;
try {
  res = await fetch(URL, {
    headers: { Accept: 'application/json' },
    signal: AbortSignal.timeout(15000),
  });
} catch (e) {
  console.error(`Could not reach VIVA: ${e?.cause?.message ?? e.message}`);
  console.error('Run this from a machine with open internet access (not the CI sandbox).');
  process.exit(1);
}
if (!res.ok) {
  console.error(`VIVA roster request failed: HTTP ${res.status}`);
  process.exit(1);
}
const data = await res.json();
const list = data?.GetStationsResult?.Stations ?? [];
const stations = list
  .filter((s) => typeof s.Lat === 'number' && typeof s.Lon === 'number')
  .map((s) => ({ id: s.ID, name: s.Name, lat: s.Lat, lon: s.Lon }))
  .sort((a, b) => a.id - b.id);

if (stations.length === 0) {
  console.error('Roster came back empty — refusing to overwrite the snapshot.');
  process.exit(1);
}

const outPath = join(dirname(fileURLToPath(import.meta.url)), '..', 'lib', 'viva-stations.snapshot.ts');
const header = `// GENERATED by scripts/snapshot-viva-stations.mjs — do not edit by hand.
// Regenerate with: npm run snapshot:viva
// Snapshot of VIVA's station roster, used as a fallback when the live
// roster request fails at runtime.
// Generated: ${new Date().toISOString()} (${stations.length} stations)

export interface VivaSnapshotStation {
  id: number;
  name: string;
  lat: number;
  lon: number;
}

export const VIVA_STATIONS_SNAPSHOT: VivaSnapshotStation[] = `;
writeFileSync(outPath, header + JSON.stringify(stations, null, 2) + ';\n');
console.log(`Wrote ${stations.length} stations to lib/viva-stations.snapshot.ts`);

const dropped = list.length - stations.length;
if (dropped > 0) console.log(`(${dropped} roster entries lacked coordinates and were skipped)`);
